#!/usr/bin/env bash
# Pin the always-on LAN host's address statically (systemd-networkd), so it can serve DHCP: a host cannot renew its own
# lease from its own DHCP server. Run ON THAT HOST as root, with the values from the private lan.env:
#     sudo bash front-static-ip.sh --iface <iface> --addr <ip>/<prefix> --gateway <ip> --dns "<ip> <ip> <ip>"
#     DRY_RUN=1 bash front-static-ip.sh ...      read-only checks and the file it would write (no root needed)
# Design: files generated by other tools (e.g. netplan's /run/systemd/network/10-netplan-*.network) are left untouched.
# networkd applies the FIRST matching .network file in alphanumeric order across /etc, /run and
# /usr/lib (systemd.network(5)), so /etc/systemd/network/05-aisis-lan-$IFACE.network wins over them.
# The .link file / fixed MAC are not involved. Auto-reverts if connectivity fails within 15 s.
set -euo pipefail

IFACE="" ADDR="" GW="" DNS_SERVERS=""
while [ $# -gt 0 ]; do
  case "$1" in
    --iface) IFACE=${2:?}; shift 2 ;;
    --addr) ADDR=${2:?}; shift 2 ;;
    --gateway) GW=${2:?}; shift 2 ;;
    --dns) DNS_SERVERS=${2:?}; shift 2 ;;
    *) echo "usage: $0 --iface IF --addr IP/PREFIX --gateway IP --dns \"IP IP ...\"" >&2; exit 2 ;;
  esac
done
[ -n "$IFACE" ] && [ -n "$ADDR" ] && [ -n "$GW" ] && [ -n "$DNS_SERVERS" ] || { echo "FAIL: --iface, --addr, --gateway and --dns are all required" >&2; exit 2; }
[[ $IFACE =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "FAIL: bad --iface" >&2; exit 2; }
FILE=/etc/systemd/network/05-aisis-lan-$IFACE.network
BACKUP_DIR=/var/backups/aisis-lan
STAMP=$(date +%Y%m%d-%H%M%S)
WATCHDOG=aisis-lan-static-ip-revert

say() { echo "==> $*"; }
die() { echo "FAIL: $*" >&2; exit 1; }

DRY_RUN=${DRY_RUN:-0}   # DRY_RUN=1: read-only pre-checks, prints the file, changes nothing (no root needed)
[ "$DRY_RUN" = 1 ] || [ "$(id -u)" -eq 0 ] || die "run as root: sudo bash $0"
for c in ip networkctl ping systemd-run; do command -v "$c" >/dev/null || die "missing $c"; done

say "Undo (also done automatically on failure):"
echo "    sudo rm -f $FILE && sudo networkctl reload && sudo networkctl reconfigure $IFACE"

# ---- pre-checks: same address, gateway as observed now -------------------------------------
cur_addr=$(ip -4 -o addr show dev "$IFACE" scope global | awk '{print $4}' | head -n1)
cur_gw=$(ip -4 route show default dev "$IFACE" | awk '/^default/ {print $3; exit}')
say "current $IFACE address: ${cur_addr:-none}  default gateway: ${cur_gw:-none}"
[ "$cur_addr" = "$ADDR" ] || die "$IFACE has ${cur_addr:-no address}, expected $ADDR (refusing to change the address)"
[ "$cur_gw" = "$GW" ] || die "default gateway is ${cur_gw:-none}, expected $GW"
[ "$DRY_RUN" = 1 ] || ping -c1 -W2 "$GW" >/dev/null || die "gateway $GW not answering before the change"
# the post-change check may only demand what answered before: a network that filters ICMP to 1.1.1.1 must still apply
had_wan=0
[ "$DRY_RUN" = 1 ] || { ping -c1 -W2 1.1.1.1 >/dev/null 2>&1 && had_wan=1 || say "note: 1.1.1.1 does not answer now; the post-change check will be gateway-only"; }

# ---- precedence check: ours must sort before every other .network that could match ----------
say "networkd file order (first match wins):"
names=$(basename "$FILE")
for f in /etc/systemd/network/*.network /run/systemd/network/*.network \
         /usr/lib/systemd/network/*.network /usr/local/lib/systemd/network/*.network; do
  [ -e "$f" ] && names+=$'\n'$(basename "$f")
done
mapfile -t ordered < <(printf '%s\n' "$names" | LC_ALL=C sort -u)
printf '    %s\n' "${ordered[@]}"
[ "${ordered[0]}" = "$(basename "$FILE")" ] || die "another .network file sorts before $(basename "$FILE"); aborting"

# ---- desired file -----------------------------------------------------------------------------
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT
{
  echo "# Managed by aisis lan front-static-ip.sh. Undo: rm this file; networkctl reload; networkctl reconfigure $IFACE"
  echo "# Overrides a generated DHCP file for this interface (this name sorts first)."
  echo "[Match]"
  echo "Name=$IFACE"
  echo
  echo "[Link]"
  echo "RequiredForOnline=routable"
  echo
  echo "[Network]"
  echo "DHCP=no"
  echo "Address=$ADDR"
  echo "Gateway=$GW"
  for d in $DNS_SERVERS; do echo "DNS=$d"; done
} > "$tmp"

if [ "$DRY_RUN" = 1 ]; then
  say "DRY_RUN: would write $FILE with:"; sed 's/^/    | /' "$tmp"; say "DRY_RUN: nothing changed"; exit 0
fi

revert() {
  say "REVERTING to the previous configuration"
  if [ -f "$BACKUP_FILE" ]; then
    install -m 0644 "$BACKUP_FILE" "$FILE"
  else
    rm -f "$FILE"
  fi
  networkctl reload
  networkctl reconfigure "$IFACE"
}

# ---- apply ------------------------------------------------------------------------------------
BACKUP_FILE=$BACKUP_DIR/05-aisis-lan-$IFACE.network.$STAMP
mkdir -p "$BACKUP_DIR"
if [ -f "$FILE" ] && cmp -s "$tmp" "$FILE"; then
  say "$FILE already has the desired content; re-applying only to verify"
  cp -a "$FILE" "$BACKUP_FILE"   # the revert/watchdog then restores this same (good) content
else
  if [ -f "$FILE" ]; then
    cp -a "$FILE" "$BACKUP_FILE"
    say "backed up old $FILE to $BACKUP_FILE"
  fi
  install -m 0644 "$tmp" "$FILE"
  say "wrote $FILE"
fi

# Safety net if this shell is killed (ssh drop) mid-apply: a transient timer restores the previous file (or removes ours
# when there was none). Arming it is mandatory: without the safety net the change is not applied.
systemctl stop "$WATCHDOG.timer" "$WATCHDOG.service" 2>/dev/null || true
systemctl reset-failed "$WATCHDOG.service" 2>/dev/null || true  # a failed earlier run stays loaded and blocks systemd-run
systemd-run --quiet --collect --unit="$WATCHDOG" --on-active=90s \
  /bin/bash -c "if [ -f '$BACKUP_FILE' ]; then install -m 0644 '$BACKUP_FILE' '$FILE'; else rm -f '$FILE'; fi; networkctl reload; networkctl reconfigure $IFACE" \
  || { revert; die "could not arm the safety-net timer; the previous configuration was restored, nothing is applied"; }
say "armed 90 s watchdog timer $WATCHDOG (disarmed on success)"
trap '' HUP

say "networkctl reload + reconfigure $IFACE"
networkctl reload
networkctl reconfigure "$IFACE"

settled=0
for _ in $(seq 1 10); do
  addrs=$(ip -4 -o addr show dev "$IFACE" scope global || true)
  if printf '%s\n' "$addrs" | grep -qF "$ADDR" && ! printf '%s\n' "$addrs" | grep -qF ' dynamic '; then settled=1; break; fi
  sleep 1
done
if [ "$settled" -ne 1 ]; then
  say "address did not settle as static $ADDR within 10 s (still dynamic or missing)"
  revert
  systemctl stop "$WATCHDOG.timer" 2>/dev/null || true
  exit 1
fi
say "$IFACE has static $ADDR"

# connectivity only after the address settled: a ping right after reconfigure can still ride the old (identical) config
ok=0
for _ in $(seq 1 15); do
  sleep 1
  if ping -c1 -W1 "$GW" >/dev/null 2>&1 && { [ "$had_wan" = 0 ] || ping -c1 -W1 1.1.1.1 >/dev/null 2>&1; }; then ok=1; break; fi
done
if [ "$ok" -ne 1 ]; then
  say "connectivity check FAILED within 15 s (gateway $GW$([ "$had_wan" = 1 ] && echo ' and 1.1.1.1'))"
  revert
  systemctl stop "$WATCHDOG.timer" 2>/dev/null || true
  exit 1
fi
say "gateway $GW reachable$([ "$had_wan" = 1 ] && echo ' and 1.1.1.1')"
systemctl stop "$WATCHDOG.timer" 2>/dev/null || true
say "watchdog disarmed"
networkctl status "$IFACE" --no-pager | grep -E 'Network File|Address|Gateway|DNS' | sed 's/^ */    /'
ip -4 -o addr show dev "$IFACE" scope global | sed 's/^/    /'
say "DONE: $IFACE is static $ADDR (gateway $GW). Undo: sudo rm -f $FILE && sudo networkctl reload && sudo networkctl reconfigure $IFACE"
